Method.Implementation:
set pResponse = ##class(IHC.ITF.DStruc.ListOfSbSb).%New()
set tSC = $$$OK
set sqlStr = "SELECT SBSB.SBSB_ID, SBSB.SBSB_CK, MEME.MEME_HICN "_ ", (CASE WHEN SBCS.CSCS_ID LIKE '%P%' THEN 'ENH2246' ELSE 'ENH1994'END) AS 'PLAN' " _ ", GRGR.GRGR_ID " _ ", CONVERT(char(8), SBCS.SBCS_EFF_DT, 112) AS EFF_DT " _ ", CONVERT(char(8), SBCS.SBCS_TERM_DT, 112) AS TERM_DT " _ "FROM CMC_SBSB_SUBSC SBSB " _ "JOIN CMC_MEME_MEMBER MEME ON SBSB.SBSB_CK = MEME.SBSB_CK " _ "JOIN CMC_GRGR_GROUP GRGR ON MEME.GRGR_CK = GRGR.GRGR_CK " _ "JOIN CMC_SBCS_CLASS SBCS ON SBSB.SBSB_CK = SBCS.SBSB_CK " _ " and SBSB.SBSB_ID = ? " _ // _ pRequest.lst.GetAt(1).SbSbId _ "'" _ "ORDER BY SBCS.SBCS_EFF_DT DESC"
try{ FOR ind=1:1:pRequest.lst.Count() {
$$$TRACE( ind _". SBSB_ID = " _ pRequest.lst.GetAt(ind).SbSbId) set arr = 1 set arr(1) = pRequest.lst.GetAt(ind).SbSbId set arr(1,"SqlType") = 12
set tSC=..Adapter.ExecuteQueryParmArray(.tResult,sqlStr, .arr)
$$$TRACE(" ExecuteQueryParmArray Status : "_tSC) if $$$ISOK(tSC) { While tResult.Next() { set facObj = ##class(IHC.ITF.DStruc.FacetsInformation).%New()
set facObj.SbSbId = pRequest.lst.GetAt(ind).SbSbId set facObj.SbSbCK = tResult.GetData(2) set facObj.Hicn = tResult.GetData(3) set facObj.Plan = tResult.GetData(4) set facObj.GrGrId = tResult.GetData(5) set facObj.EffDt = tResult.GetData(6) set facObj.TermDt = tResult.GetData(7) Do pResponse.lst.Insert(facObj)
set StringValue = facObj.SbSbId _", " _ facObj.Hicn _", " _ facObj.Plan _", " _ facObj.GrGrId $$$TRACE("ExecuteQueryParmArray Return Values:" _ StringValue)
} } else { set tSC = $$$ERROR( "SQLError:Executing Query " _ tSC) } }
Do pResponse.%Save()
$$$TRACE("IDs: " _ pRequest.%Id() _", " _ pResponse.%Id()) }CATCH err { $$$LOGERROR( "Error while Executing Query " _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) set tSC = $$$ERROR( "SQLError:Executing Query " _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) }
return tSC
